basicCode.vanilla:
import { createComposerModelPicker } from '@/components/ui/composer-model-picker';
import { createComposer } from '@/components/ui/composer';

const picker = createComposerModelPicker({
  labels: pickerLabels,
  models,
  value: 'fast',
  onValueChange: (model) => escolher(model.id),
});

const composer = createComposer({ labels, railStart: [picker] });

basicCode.react:
import { ComposerModelPicker } from "@/components/ui/composer-model-picker";
import { Composer } from "@/components/ui/composer";

<Composer
  labels={labels}
  railStart={
    <ComposerModelPicker
      labels={pickerLabels}
      models={models}
      value={escolhido}
      onValueChange={(model) => escolher(model.id)}
    />
  }
/>

withUnavailableCode.web:
// Um modelo que pode responder. A descrição aparece na lista, e não no
// gatilho: um trilho é estreito, e o nome é o que se confere de relance.
{ id: 'fast', label: 'Rápido', description: 'Responde em segundos.' }

// Indisponível vem com MOTIVO, sempre. Opção apagada sem explicação é a
// pergunta "por que não posso?" sem resposta na tela — e quem não enxerga o
// cinza não recebe nem a pista.
{
  id: 'deep',
  label: 'Profundo',
  description: 'Lê a obra inteira antes de responder.',
  unavailable: true,
  unavailableReason: 'Fora do seu plano.',
}

extensibilityCode.web:
// O modelo é DADO, e o componente não sabe o que ele significa.
// Quanto custa, quem tem direito e o que acontece depois da troca é de quem
// monta a conversa.
{
  id: 'balanced',            // o endereço, que identifica a escolha
  label: 'Equilibrado',      // o nome curto, que vai para o gatilho
  description: 'O meio-termo entre esperar e acertar.',
  badge: 'Novo',             // reforço; nunca a única portadora
  unavailable: false,        // verdadeiro exige o motivo abaixo
  unavailableReason: undefined,
}

customizationCode.web:
.nds-composer-model-panel {
  max-inline-size: 24rem;
}

/* A etiqueta é REFORÇO, e não a pista: o que muda a escolha também está
   escrito na descrição, porque forma e cor sozinhas não descrevem
   condição (WCAG 1.4.1). */
.nds-composer-model-badge {
  text-transform: uppercase;
}

